import React, {act} from 'react';
import {createRoot} from 'react-dom/client';
import {readFileSync} from 'node:fs';
import {it, expect, vi} from 'vitest';
import ReportRuntime from './ReportRuntime.jsx';

// Generated by converter/assembly TestGeneratedCompleteTableRuntimeFixture.
// The definition, native reader/compose result and actual fill are assembled;
// no hand-authored report bindings or substitute table rows appear in this test.
const fixturePath = process.env.CONVERTER_RUNTIME_FIXTURE;
const run = fixturePath ? it : it.skip;
run('sorts and pages a complete assembled native result locally without backend query changes', async () => {
  globalThis.IS_REACT_ACT_ENVIRONMENT = true;
  const fixture = JSON.parse(readFileSync(fixturePath, 'utf8'));
  const before = JSON.stringify(fixture.reportSpec.datasets);
  const fetchPage = vi.fn();
  const host = document.createElement('div'); document.body.append(host);
  const root = createRoot(host);
  const rows = () => [...host.querySelectorAll('.forge-report-runtime-table-panel tbody tr')];
  const click = async selector => act(async () => {
    const element = host.querySelector(selector);
    expect(element, selector).not.toBeNull(); element.click();
  });
  try {
    await act(async () => root.render(<ReportRuntime reportSpec={fixture.reportSpec} reportFill={fixture.reportFill} onDatasetPageChange={fetchPage}/>));
    expect(rows()).toHaveLength(143);
    await click('[aria-label="Paginate High"]');
    expect(rows()).toHaveLength(25);
    expect(host.textContent).toContain('Rows 1–25 of 143');
    await click('.forge-dashboard-table-pager button:last-child');
    expect(host.textContent).toContain('Rows 26–50 of 143');
    await click('[aria-label="Sort by Amount"]');
    await click('[aria-label="Sort by Amount"]');
    expect(host.textContent).toContain('Rows 1–25 of 143');
    expect(rows()[0].textContent).toContain('143');
    expect(fetchPage).not.toHaveBeenCalled();
    expect(JSON.stringify(fixture.reportSpec.datasets)).toBe(before);
  } finally { await act(async () => root.unmount()); host.remove(); }
});
